use std::{alloc::{GlobalAlloc,Layout,System},cell::Cell};

#[derive(Default, Copy, Clone, Debug)]
pub(crate) struct Live {
    now: isize, pub peak: isize, pub metadata: Option<isize>, pub statuses: Option<isize>,
}
thread_local! { static LIVE: Cell<Option<Live>> = const { Cell::new(None) }; }
struct Alloc;
#[global_allocator] static COUNT: Alloc = Alloc;
fn update(f: impl FnOnce(&mut Live)) {
    let _ = LIVE.try_with(|slot| {
        if let Some(mut state) = slot.get() {f(&mut state); slot.set(Some(state));}
    });
}
fn change(delta:isize) {
    update(|s| { s.now += delta; s.peak = s.peak.max(s.now); });
}
unsafe impl GlobalAlloc for Alloc {
    unsafe fn alloc(&self,l:Layout)->*mut u8 {
        let p=unsafe {System.alloc(l)};
        if !p.is_null() {change(l.size() as isize);}
        p
    }
    unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8 {
        let p=unsafe {System.alloc_zeroed(l)};
        if !p.is_null() {change(l.size() as isize);}
        p
    }
    unsafe fn dealloc(&self,p:*mut u8,l:Layout) {
        unsafe {System.dealloc(p,l)};
        change(-(l.size() as isize));
    }
    unsafe fn realloc(&self,p:*mut u8,l:Layout,s:usize)->*mut u8 {
        let p=unsafe {System.realloc(p,l,s)};
        if !p.is_null() {change(s as isize-l.size() as isize);}
        p
    }
}
pub(crate) fn metadata() {update(|s| s.metadata=Some(s.now));}
pub(crate) fn statuses() {update(|s| s.statuses=Some(s.now));}
struct Reset;
impl Drop for Reset { fn drop(&mut self){let _=LIVE.try_with(|s|s.set(None));} }
pub(crate) fn measure<T>(f:impl FnOnce()->T)->(T, Live,isize) {
    assert!(LIVE.with(|s|s.replace(Some(Live::default()))).is_none());
    let _guard=Reset;
    let value=f();
    let live=LIVE.with(|s|s.get().unwrap());
    (value,live,live.now)
}

