#[test]
fn w331_finalization_scratch_live_bytes() {
    use crate::{app_server::transcript::journal::source::transcript_from_scan,
        domain::{SessionId, SubagentSessionBinding}};
    for n in [0, 1, 256, 4096] {
        let mut records=Vec::new();
        let mut expected=Vec::new();
        let (session, thread, turn)=(SessionId::from_u128(1), ThreadId::from_u128(2), TurnId::from_u128(3));
        for i in 0..n {
            let id=format!("fixture-{i:04}");
            let call=ToolCall::new(id.clone(),"fixture",json!({}));
            let mut msg=CanonicalMessage::new(MessageRole::Assistant,vec![ContentPart::ToolCall{call}]);
            msg.id=crate::domain::MessageId::from_u128(100+i as u128);
            msg.parts[0].part_id=PartId::from_u128(10000+i as u128);
            records.push(record(session,None,thread,turn,(2*i+1) as u64,JournalEntry::HistoryMutated(HistoryMutated{
                previous_revision:i as u64,new_revision:i as u64+1,mutation:HistoryMutationKind::Append,
                messages:vec![msg],compaction:None,tool_results:vec![],
            })));
            let binding=SubagentSessionBinding{
                source_call_id:id.clone(),child_thread_id:ThreadId::from_u128(10000+i as u128),
                session_id:SessionId::from_u128(20000+i as u128),session_dir:"/synthetic/child".into(),
            };
            expected.push((id,json!({"tool":"fixture","child_thread_id":binding.child_thread_id,
                "subagent_session":{"session_id":binding.session_id,"session_dir":binding.session_dir}})));
            records.push(record(session,None,thread,turn,(2*i+2) as u64,JournalEntry::SubagentSessionBoundRecorded(binding)));
        }
        let (rows,m,end)=crate::w331_alloc::measure(||transcript_from_scan(|visit| {
            for record in &records {visit(record.clone())?;}
            Ok(())
        },None).unwrap());
        assert_eq!(rows.len(), n);
        for (row,(id,metadata)) in rows.iter().zip(expected) {
            let tool=row.tool.as_ref().unwrap();
            assert_eq!(tool.call_id,id);
            assert_eq!(tool.metadata,metadata);
            assert_eq!(tool.status,"interrupted");
        }
        if let Some(dir)=std::env::var_os("W331_WITNESS_DIR") {
            std::fs::write(std::path::PathBuf::from(dir).join(format!("{n}.json")),serde_json::to_vec(&rows).unwrap()).unwrap();
        }
        eprintln!("W331 {n} {} {} {} {end}",m.metadata.unwrap(),m.statuses.unwrap(),m.peak);
    }
}
